CREATE TABLE IF NOT EXISTS agent_channels (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL, title TEXT NOT NULL, provider_binding_id TEXT, system_prompt TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS agent_channels_workspace_idx ON agent_channels (workspace_id);
CREATE TABLE IF NOT EXISTS agent_messages (id TEXT PRIMARY KEY NOT NULL, channel_id TEXT NOT NULL REFERENCES agent_channels(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, metadata_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS agent_messages_channel_idx ON agent_messages (channel_id, created_at);
CREATE TABLE IF NOT EXISTS agent_provider_bindings (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL, contribution_id TEXT NOT NULL, title TEXT NOT NULL, model TEXT NOT NULL, status TEXT NOT NULL, secret_ref TEXT, configuration_json TEXT, detected_models_json TEXT, detected_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS agent_provider_bindings_workspace_idx ON agent_provider_bindings (workspace_id);
CREATE UNIQUE INDEX IF NOT EXISTS agent_provider_binding_name_idx ON agent_provider_bindings (workspace_id, title);
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY NOT NULL, channel_id TEXT NOT NULL REFERENCES agent_channels(id) ON DELETE CASCADE, provider_binding_id TEXT REFERENCES agent_provider_bindings(id), status TEXT NOT NULL, input_message_id TEXT REFERENCES agent_messages(id), output_message_id TEXT REFERENCES agent_messages(id), error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE INDEX IF NOT EXISTS agent_runs_channel_idx ON agent_runs (channel_id, created_at);
CREATE TABLE IF NOT EXISTS agent_knowledge_sources (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', resource_ref TEXT, source_url TEXT, configuration_json TEXT, last_synced_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS agent_knowledge_sources_workspace_idx ON agent_knowledge_sources (workspace_id);
CREATE TABLE IF NOT EXISTS agent_tool_calls (id TEXT PRIMARY KEY NOT NULL, run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, tool_id TEXT NOT NULL, approval_status TEXT NOT NULL, input_json TEXT, output_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS agent_tool_calls_run_idx ON agent_tool_calls (run_id);
CREATE TABLE IF NOT EXISTS agent_resource_bindings (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL, resource_type TEXT NOT NULL, binding_name TEXT NOT NULL, purpose TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS agent_resource_binding_idx ON agent_resource_bindings (workspace_id, resource_type, binding_name);
